const s = wb.getWorksheet('Sheet1');
for (let r = 2; r <= 16; r++) {
  s.getRange(`B${r}`).setValue(`=IF(A${r}>0,A${r}/MAX($A$2:$A$16)*5,IF(A${r}<0,-A${r}/MIN($A$2:$A$16)*5,0))`);
}
const out = [];
for (let r = 2; r <= 16; r++) {
  const c = s.getRange(`B${r}`);
  const v = c.getValue();
  const isInt = Math.abs(v - Math.round(v)) < 1e-9;
  const isOne = Math.abs(v * 10 - Math.round(v * 10)) < 1e-9;
  const fmt = isInt ? '0' : isOne ? '0.0' : '0.00000000000';
  c.getStyle().setNumberFormat(fmt);
  c.getStyle().setFill('#A6A6A6');
  out.push(`B${r} A=${s.getRange(`A${r}`).getValue()} v=${v} fmt=${fmt}`);
}
log(out.join('\n'));
